/// фронтранера, гейт «те же круги»), `market` — немедленный рыночный вход
/// (GTC, гарантированно пересекает спред — не мейкер) или
/// `ladder<N>x<from>..<to>[w<k>]` — `N` ног от `from` до `to` bps над
/// стеной (для аска — под), равными долями либо весом нижней ноги `k`.
/// Числа — из имени формы (предрегистрация), умолчаний нет.
#[arg(long = "entry-form")]
pub entry_form: Vec<String>,
/// Форма выхода (F7 этапа F, Б-75) — повторяемый флаг, ось сетки:
/// `none` (умолчание — прежнее поведение, гейт «те же круги»), `eat<X>`
/// (стена съедена сделками ≥ X %) или `gone<W>` (стена снята без сделок,
/// размер < (1−W %) от входа, съедение < половины падения) и её продолжения:
/// `gone<W>tr<T>` (трейл после снятия), `gone<W>be`/`gone<W>bex` (стоп в
/// безубыток), `gone<W>wall<B>`/`gone<W>wallx<B>`/`gone<W>wallk<B>` (стоп на
/// уровень стены с буфером `B` bps за ней; позиция хуже нового стопа на
/// снятии: без буквы — перенос при возврате цены, `x` — выход сразу, `k` —
/// стоп плана до конца сделки). Числа — из предрегистрации, умолчаний в коде нет.
#[arg(long = "exit-form")]
pub exit_form: Vec<String>,
/// Выход по «прилипанию» (B4, В-58 п. 5; ось сетки — аудит дизайна 22.09, В-85) —
/// повторяемый флаг: `off` или секунды из предрегистрированного набора В-58 (1, 2, 3).
/// Без флага ось выключена — прежние формы и имена (гейт «те же круги»).
#[arg(long = "early-exit-secs")]
pub early_exit_secs: Vec<String>,
/// Набор фильтров касаний одним процессом (повторяемый): `<имя>:<k=v,…>`,
/// ключи `age=<с>` (возраст ≥, как `--min-age-secs`), `flow=<%>` (сила
/// ×поток ≥, как `--min-flow-pct`), `side=bid|ask`, `frontrun` (только
/// от фронтрана); пустой список ключей — без фильтров (`name:`). Артефакты
/// набора — `<out-dir>/<имя>/`; имя — буквы, цифры, `.`, `_`, `-`. С
/// `--set` флаги `--min-age-secs/--min-flow-pct/--side/--frontrun-only`
/// у команды — отказ.
#[arg(long = "set")]
pub sets: Vec<String>,
/// Список клеток вместо декартова произведения (T-38, владелец 27.09: «на одни сутки сразу все гипотезы»):
/// файл, строка — `<имя формы> <набор>` (имя — как в `forms.csv`, набор — имя из `--set`; пустые строки и
/// `#…` — пропуск). Оси `--entry-form/--stop-form/--take-form/--deadline-secs/…` задают словарь форм, файл —
/// какие из них считать и в каком наборе; формы вне файла не считаются. Без флага — прежнее произведение.
#[arg(long)]
pub cells: Option<PathBuf>,
/// σ монеты на взводе для σ-лестницы `--entry-form ladder<N>x<a>..<b>s[w<k>]` (В-131): каталог с
/// `sigma-<SYMBOL>.csv` (`window_end_ms,sigma_bps`, `tools/compute/sigma-table.py`). Обязателен при
/// σ-лестнице и запрещён без неё; сигнал без σ не торгуется и считается в `n_no_sigma` итога.
#[arg(long)]
pub sigma_from: Option<PathBuf>,
/// Режим по минутам для ключей `pool*`/`btc*` наборов (S3/S4 плана по
/// сторонам): каталог `study/regime` с `<сутки>.csv` от `regime.py`.
/// Без него эти ключи — отказ; сутки без файла — отказ.
#[arg(long)]
pub regime_from: Option<PathBuf>,
/// Дедлайны сетки, секунды (повторяемый; умолчание — В-58 `60 600 3600
/// 7200`); разрешены ещё `1800` и `14400` (S8, предрегистрация 20.09) —
/// иное число отказ.
#[arg(long = "deadline-secs")]
pub deadline_secs: Vec<u64>,
#[command(flatten)]
pub h3: H3Args,
#[arg(long)]
pub h3_k: Option<f64>,
#[arg(long)]
pub warmup_ms: Option<i64>,
#[arg(long)]
pub repeat_window_ms: Option<i64>,
/// Потоков на сетку (умолчание — число ядер).
#[arg(long)]
pub threads: Option<usize>,
/// Драйвер: `setups` — биржа только от касания до конца круга (умолчание,
/// решение владельца 2026-09-18); `full` — сплошной прогон суток на форму,
/// эталон для гейта «побайтово те же круги».
#[arg(long, value_enum, default_value_t = DriverArg::Setups)]
pub driver: DriverArg,
/// Память кругов (G10, владелец 2026-09-23: «ускорить бэктест без потерь»): круг формы, уже
/// посчитанный для одного набора, остальные наборы берут готовым — итог побайтово тот же.
/// `off` — прежний счёт каждого набора с нуля (гейт «те же байты»). Только `--driver setups`.
#[arg(long = "round-memo", default_value = "on", value_parser = ["on", "off"])]
pub round_memo: String,
/// Пропуск «позиция занята» (T-31, П-02 §12, В-117): `on` — прежнее поведение (сигнал, пока круг формы
/// на монете не вернулся в `Idle`, — промах `n_busy`). `off` — каждый сигнал набора свой круг, обрыв
/// суток счёт не прерывает, рядом с `rounds.csv` (все исполненные круги) пишется `signals.csv` — след
/// каждого шага (`idle_ns`, остаток); занятость потом решает `tools/compute/busy-replay.py` тем же
/// правилом, уже после фильтра признаков. `forms.csv` при `off` — счётчики без пропуска (не эталон).
/// Только `--driver setups` (круг — свежий движок над окном `t0`, перекрытые круги независимы).
#[arg(long = "busy-skip", default_value = "on", value_parser = ["on", "off"])]
pub busy_skip: String,
/// Сверка окон (К3, условие Судьи b86eed6): кроме своей книги окон (`WindowDepth`) строит
/// окна прежним путём на книге крейта и сравнивает каждый снимок по всем полям; расхождение —
/// отказ с `t0` и полем. Итог счёта не меняет. Только `--driver setups`.
#[arg(long, default_value_t = false)]
pub windows_check: bool,
/// Вид событий суток (CEO 26.09, ночь до Р5): `compact` — 32-байтные строки Р6, круг
/// разворачивается в свой буфер (память вдвое меньше); `wide` — сутки разворачиваются
/// один раз в 64-байтные строки крейта, круги берут их срезом без копии (скорость и
/// память — как до Р6). Итог побайтно тот же; тяжёлым суткам (LSK 14.09) — `compact`.

    // Прежний режим (`touch`): условие выключено, число не читается.
    None => 0.0,
};
let entries = parse_entry_forms(&args.entry_form)?;
// В-131: σ-лестнице — таблица σ на взводе (`--sigma-from`); таблица без σ-лестницы не читается — отказ,
// чтобы флаг не создавал видимость, что σ где-то учтена.
let sigma_entries = entries
    .iter()
    .any(|e| matches!(e, EntryForm::LadderSigma { .. }));
anyhow::ensure!(
    !sigma_entries || args.sigma_from.is_some(),
    "--entry-form ladder…s: σ-лестнице (В-131) нужен --sigma-from <каталог> (sigma-<SYMBOL>.csv, tools/compute/sigma-table.py)"
);
anyhow::ensure!(
    sigma_entries || args.sigma_from.is_none(),
    "--sigma-from без σ-лестницы в --entry-form — таблицу σ никто не читает"
);
let exits = parse_exit_forms(&args.exit_form)?;
let earlies = parse_early_exits(&args.early_exit_secs)?;
let forms = grid_forms_with_early(
    &stops,
    &takes,
    args.take_floor_fees,
    &deadlines,
    &entry_ttls,
    &entries,
    &exits,
    &earlies,
);
{
    let labels: std::collections::BTreeSet<&str> = forms.iter().map(|f| f.label).collect();
    anyhow::ensure!(
        labels.len() == forms.len(),
        "сетка: повторяющиеся формы в --stop-form/--take-form/--entry-ttl-secs/--entry-form/--exit-form/--early-exit-secs дают одинаковые имена"
    );
}
// F6 (В-73): сигнал по записи подхода — только из кэша F1, реплея
// подходов у сетки нет (полосу `D` выбирает прогон `lob touches
// --approach-bps`; в часы ночи их пишет шаг H3).
if args.signal == SignalArg::Approach {
    anyhow::ensure!(
        args.touches_from.is_some(),
        "--signal approach: нужен кэш подходов --touches-from <dir> (approaches-<SYMBOL>.csv, F1) — реплей подходов сетка не считает"
    );
}
if let Some(dir) = &args.touches_from {
    anyhow::ensure!(dir.is_dir(), "--touches-from {}: не каталог", dir.display());
    anyhow::ensure!(
        !forms.iter().any(|f| f.form.needs_sigma()),
        "--touches-from: σ-формы (s<a>/t<b>) требуют реплея — σ в CSV касаний суточная и с шестью знаками"
    );
    anyhow::ensure!(
        args.warmup_ms.is_none() && args.repeat_window_ms.is_none(),
        "--touches-from: прогрев и окно повтора трекера — умолчания, как у ночного `lob touches`"
    );
}
let sets: Vec<FilterSet> = if args.sets.is_empty() {
    vec![FilterSet::from_args(args)]
} else {
    anyhow::ensure!(
        !args.frontrun_only
            && args.min_age_secs.is_none()
            && args.min_flow_pct.is_none()
            && args.side.is_none(),
        "--set задан: фильтры касаний только в наборах, флаги --min-age-secs/--min-flow-pct/--side/--frontrun-only у команды — отказ"
    );
    let parsed = args
        .sets
        .iter()
        .map(|s| FilterSet::parse(s))
        .collect::<anyhow::Result<Vec<_>>>()?;
    let names: std::collections::BTreeSet<&str> =
        parsed.iter().map(|s| s.name.as_str()).collect();
    anyhow::ensure!(
        names.len() == parsed.len(),
        "--set: имена наборов повторяются"
    );
    parsed
