pub fn grid_forms_with_early(
    stops: &[StopForm],
    takes: &[TakeForm],
    take_floor_fees: Option<f64>,
    deadlines: &[u64],
    ttls: &[EntryTtl],
    entries: &[EntryForm],
    exits: &[ExitForm],
    earlies: &[Option<i64>],
) -> Vec<GridForm> {
