        stops,
        takes,
        take_floor_fees,
        deadlines,
        ttls,
        entries,
        exits,
    );
    let mut out = Vec::with_capacity(base.len() * earlies.len());
    for &early in earlies {
        for f in &base {
            let mut g = *f;
            if let Some(x) = early {
                g.label = Box::leak(format!("{}-early{x}", f.label).into_boxed_str());
                g.early_exit_secs = Some(x);
            }
            out.push(g);
        }
    }
    out
}

